BATCH={'key':'troy_qbqw','label':'Lansingburgh and central Troy: churches, the Melville house, the Lion Factory','added':'2026-11-19 03:44'}
LHS=lambda t,p:L('Lansingburgh Historical Society: '+t,'https://www.lansingburghhistoricalsociety.org/'+p)
